// 配置参数
const accountName = '饼干哥哥AGI';
const apiKey = 'JZLdc9670be1403c05cJZLdc9670be1403c05c';
const baseUrl = 'https://www.dajiala.com/fbmain/monitor/v3/post_history';
return [{json: {accountName, apiKey, baseUrl, currentPage: 1, allArticles: [], maxPages: 100}}];

const response = $input.first().json;
if (response.code !== 0) {
  if (response.code === 110) {
    return [{json: {...$input.first().json, hasMore: false}}];
  }
  throw new Error(`API错误: ${response.msg}`);
}
const articles = response.data || [];
const totalPage = response.total_page || 1;
const currentPage = $input.first().json.currentPage;
const allArticles = $input.first().json.allArticles || [];
allArticles.push(...articles);
const hasMore = currentPage < totalPage && currentPage < $input.first().json.maxPages;
console.log(`第 ${currentPage} 页: ${articles.length} 篇, 累计 ${allArticles.length} 篇`);
return [{json: {...$input.first().json, articles, allArticles, totalPages: totalPage, hasMore, nextPage: currentPage + 1}}];

const data = $input.first().json;
return data.allArticles.map((article, index) => ({
  json: {
    articleIndex: index,
    article: {
      title: article.title,
      url: article.url,
      publishTime: article.post_time_str,
      digest: article.digest,
      coverUrl: article.cover_url
    }
  }
}));

const html = $input.first().json.data || '';
const title = $input.first().json.article.title;
let content = html.replace(/<script[^>]*>[\s\S]*?</script>/gi, '').replace(/<style[^>]*>[\s\S]*?</style>/gi, '').replace(/<[^>]+>/g, '
').replace(/

+/g, '

').trim();
if (content.length > 5000) content = content.substring(0, 5000) + '...';
return [{json: {...$input.first().json, markdownContent: `# ${title}

${content}`, contentLength: content.length}}];

const input = $input.first().json;
return [{
  json: {
    title: input.article.title,
    url: input.article.url,
    publishTime: input.article.publishTime,
    digest: input.article.digest,
    content: input.markdownContent,
    contentLength: input.contentLength,
    fetchedAt: new Date().toISOString()
  }
}];
